import {gameFrame,shape} from '../ui.js';
import {canRespondWithSpace} from '../interactions.js';
export function mountGame(root,c){let trial=0,target=false,live=false,responded=false,shown=0,hits=0,misses=0,falseAlarms=0,correctHolds=0;const times=[];const area=gameFrame(root,'Wait for the red dot','Press Respond or Space for red dots. Ignore blue diamonds.');area.innerHTML='<div class="pulse-stage" aria-label="Stimulus area"><span>Get ready</span></div><button id="respond" class="primary pulse-button">Respond <kbd>Space</kbd></button><p class="subtle" id="pulse-status">Wait for the first stimulus.</p>';const stage=area.querySelector('.pulse-stage'),status=area.querySelector('#pulse-status');function update(){Object.assign(c.metrics,{hits,misses,falseAlarms,correctHolds,reactionMs:times.length?Math.round(times.reduce((a,b)=>a+b,0)/times.length):null});c.updateScore();}function respond(){if(!live||responded)return;responded=true;if(target){hits++;times.push(performance.now()-shown);}else falseAlarms++;c.session.answer(trial,target);status.textContent=target?'Target caught.':'That was a distractor. Wait for a red dot.';update();}function next(){if(c.mode==='learn'&&trial>=20){c.complete();return;}trial++;c.setRound(trial);live=false;responded=false;stage.innerHTML='<span class="pulse-wait">Wait…</span>';c.session.schedule(()=>{target=Math.random()<.45;live=true;shown=performance.now();stage.innerHTML=target?'<span class="red-dot"></span>':shape('diamond','#245de8',105);status.textContent='';c.session.schedule(()=>{live=false;if(!responded){if(target)misses++;else correctHolds++;c.session.answer(trial,!target);status.textContent=target?'Missed target.':'Good hold.';}update();next();},c.difficulty==='easy'?1200:c.difficulty==='hard'?550:850);},400+Math.random()*700);}area.querySelector('#respond').onclick=respond;const key=e=>{if(e.code==='Space'&&!e.repeat&&c.session.isActive()&&canRespondWithSpace({tag:document.activeElement?.tagName,isResponse:document.activeElement===area.querySelector('#respond'),dialogOpen:!!document.querySelector('dialog[open]'),editable:document.activeElement?.isContentEditable})){e.preventDefault();respond();}};document.addEventListener('keydown',key);next();return {dispose(){document.removeEventListener('keydown',key);}};}
